import matplotlib.pyplot as plt
import numpy as np

def plotpath(x_pos_list ,y_pos_list):
    x = x_pos_list  #x postion
    y = y_pos_list  #y postion

    # Create the plot
    plt.figure(figsize=(8, 7))         
    plt.plot(x, y, label='object path', color='red', linewidth=1, marker='o', markersize=2)

    # Add labels and title
    plt.xlabel('X-axis')
    plt.ylabel('Y-axis')
    plt.title('postion tracker')

    # Add grid and legend
    plt.grid(True, linestyle='--', alpha=0.6)
    plt.legend()

    # Show the plot
    plt.show()


